<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Customer;use App\Models\CustomerLedger;use App\Models\Payment;use App\Support\BusinessAccess;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PaymentController extends Controller{
 public function index(Request $r){BusinessAccess::requireRole($r,['owner','manager','accountant','salesperson','super_admin']);$q=Payment::with(['customer','invoice:id,invoice_number'])->where('business_id',BusinessAccess::id($r));BusinessAccess::scopeBranch($q,$r);if($r->user()->role==='salesperson')$q->where('user_id',$r->user()->id);return response()->json(['data'=>$q->latest('collection_date')->paginate($r->integer('per_page',20))]);}
 public function store(Request $r){BusinessAccess::requireRole($r,['owner','manager','accountant','salesperson','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['branch_id'=>['required','integer','exists:branches,id'],'customer_id'=>['required','integer','exists:customers,id'],'amount'=>['required','numeric','gt:0'],'method'=>['required','in:cash,bank,bkash,nagad'],'transaction_id'=>['nullable','string','max:100'],'collection_date'=>['nullable','date'],'notes'=>['nullable','string']]);BusinessAccess::branch($r,$data['branch_id']);if($data['method']!=='cash')abort_if(empty($data['transaction_id']),422,'Transaction ID is required for digital payments.');return DB::transaction(function()use($data,$r,$business){$customer=Customer::where('business_id',$business)->lockForUpdate()->findOrFail($data['customer_id']);abort_if($data['amount']>$customer->current_due,422,'Collection exceeds current due.');$number='RCT-'.now()->format('YmdHis').'-'.random_int(100,999);$payment=Payment::create([...$data,'business_id'=>$business,'user_id'=>$r->user()->id,'collection_date'=>$data['collection_date']??today(),'receipt_number'=>$number,'status'=>'completed']);$balance=$customer->current_due-$data['amount'];$customer->update(['current_due'=>$balance,'due_since'=>$balance==0?null:$customer->due_since]);CustomerLedger::create(['customer_id'=>$customer->id,'branch_id'=>$data['branch_id'],'entry_date'=>$payment->collection_date,'type'=>'payment','reference'=>$number,'debit'=>0,'credit'=>$data['amount'],'balance'=>$balance,'notes'=>$data['notes']??null]);return response()->json(['data'=>$payment->load('customer')],201);});}
 public function show(Request $r,Payment $payment){BusinessAccess::requireRole($r,['owner','manager','accountant','salesperson','super_admin']);abort_unless($payment->business_id===BusinessAccess::id($r),403);BusinessAccess::branch($r,$payment->branch_id);if($r->user()->role==='salesperson')abort_unless($payment->user_id===$r->user()->id,403);return response()->json(['data'=>$payment->load(['customer','invoice'])]);}
}
